// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ResourceProfile) predicate.ResourceProfile {
	return predicate.ResourceProfile(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ResourceProfile) predicate.ResourceProfile {
	return predicate.ResourceProfile(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ResourceProfile) predicate.ResourceProfile {
	return predicate.ResourceProfile(sql.NotPredicates(p))
}
